1	package mysql
2	
3	import (
4		"context"
5		"database/sql"
6	
7		"github.com/go-sql-driver/mysql"
8		"github.com/pkg/errors"
9	
10		"github.com/usememos/memos/internal/profile"
11		"github.com/usememos/memos/store"
12	)
13	
14	type DB struct {
15		db      *sql.DB
16		profile *profile.Profile
17		config  *mysql.Config
18	}
19	
20	func NewDB(profile *profile.Profile) (store.Driver, error) {
21		// Open MySQL connection with parameter.
22		// multiStatements=true is required for migration.
23		// See more in: https://github.com/go-sql-driver/mysql#multistatements
24		dsn, err := mergeDSN(profile.DSN)
25		if err != nil {
26			return nil, err
27		}
28	
29		driver := DB{profile: profile}
30		driver.config, err = mysql.ParseDSN(dsn)
31		if err != nil {
32			return nil, errors.New("Parse DSN error")
33		}
34	
35		driver.db, err = sql.Open("mysql", dsn)
36		if err != nil {
37			return nil, errors.Wrapf(err, "failed to open db: %s", profile.DSN)
38		}
39	
40		return &driver, nil
41	}
42	
43	func (d *DB) GetDB() *sql.DB {
44		return d.db
45	}
46	
47	func (d *DB) Close() error {
48		return d.db.Close()
49	}
50	
51	func (d *DB) IsInitialized(ctx context.Context) (bool, error) {
52		var exists bool
53		err := d.db.QueryRowContext(ctx, "SELECT EXISTS (SELECT 1 FROM information_schema.tables WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'memo' AND TABLE_TYPE = 'BASE TABLE')").Scan(&exists)
54		if err != nil {
55			return false, errors.Wrap(err, "failed to check if database is initialized")
56		}
57		return exists, nil
58	}
59	
60	// GetDatabaseSize returns the database size in bytes, or -1 if unavailable.
61	func (d *DB) GetDatabaseSize(ctx context.Context) (int64, error) {
62		var size int64
63		const q = `SELECT COALESCE(SUM(data_length + index_length), 0)
64		           FROM information_schema.tables
65		           WHERE table_schema = DATABASE()`
66		if err := d.db.QueryRowContext(ctx, q).Scan(&size); err != nil {
67			return -1, errors.Wrap(err, "failed to query mysql database size")
68		}
69		return size, nil
70	}
71	
72	func mergeDSN(baseDSN string) (string, error) {
73		config, err := mysql.ParseDSN(baseDSN)
74		if err != nil {
75			return "", errors.Wrapf(err, "failed to parse DSN: %s", baseDSN)
76		}
77	
78		config.MultiStatements = true
79		return config.FormatDSN(), nil
80	}
