1	package mysql
2	
3	import (
4		"context"
5		"database/sql"
6	
7		mysqldriver "github.com/go-sql-driver/mysql"
8		"github.com/pkg/errors"
9	
10		"github.com/usememos/memos/store"
11	)
12	
13	// IsRetryableAuthenticationMutationError reports whether err is a transient MySQL transaction failure.
14	func (*DB) IsRetryableAuthenticationMutationError(err error) bool {
15		var mysqlErr *mysqldriver.MySQLError
16		if !errors.As(err, &mysqlErr) {
17			return false
18		}
19		return mysqlErr.Number == 1205 || mysqlErr.Number == 1213
20	}
21	
22	// ApplyAuthenticationConfigMutation validates and applies an auth mutation in a serializable transaction.
23	func (d *DB) ApplyAuthenticationConfigMutation(ctx context.Context, mutation *store.AuthenticationConfigMutation) error {
24		tx, err := d.db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
25		if err != nil {
26			return errors.Wrap(err, "failed to begin authentication configuration transaction")
27		}
28		defer func() {
29			_ = tx.Rollback()
30		}()
31	
32		state := &store.AuthenticationConfigState{}
33		general := &store.InstanceSetting{}
34		err = tx.QueryRowContext(ctx, "SELECT `name`, `value`, `description` FROM `system_setting` WHERE `name` = ? FOR UPDATE", "GENERAL").Scan(
35			&general.Name, &general.Value, &general.Description,
36		)
37		if err == nil {
38			state.GeneralSetting = general
39		} else if !errors.Is(err, sql.ErrNoRows) {
40			return errors.Wrap(err, "failed to read GENERAL setting")
41		}
42		rows, err := tx.QueryContext(ctx, "SELECT `id`, `uid` FROM `idp` ORDER BY `id` FOR UPDATE")
43		if err != nil {
44			return errors.Wrap(err, "failed to read identity providers")
45		}
46		defer rows.Close()
47		for rows.Next() {
48			provider := &store.IdentityProvider{}
49			if err := rows.Scan(&provider.ID, &provider.UID); err != nil {
50				rows.Close()
51				return errors.Wrap(err, "failed to scan identity provider")
52			}
53			state.IdentityProviders = append(state.IdentityProviders, provider)
54		}
55		if err := rows.Err(); err != nil {
56			rows.Close()
57			return errors.Wrap(err, "failed to iterate identity providers")
58		}
59		if err := rows.Close(); err != nil {
60			return errors.Wrap(err, "failed to close identity provider rows")
61		}
62		if mutation.Validate != nil {
63			if err := mutation.Validate(state); err != nil {
64				return err
65			}
66		}
67		if setting := mutation.UpsertGeneralSetting; setting != nil {
68			_, err = tx.ExecContext(ctx, "INSERT INTO `system_setting` (`name`, `value`, `description`) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE `value` = ?, `description` = ?", setting.Name, setting.Value, setting.Description, setting.Value, setting.Description)
69		} else if id := mutation.DeleteIdentityProviderID; id != nil {
70			_, err = tx.ExecContext(ctx, "DELETE FROM `idp` WHERE `id` = ?", *id)
71		} else {
72			return errors.New("authentication configuration mutation has no operation")
73		}
74		if err != nil {
75			return errors.Wrap(err, "failed to apply authentication configuration mutation")
76		}
77		if err := tx.Commit(); err != nil {
78			return errors.Wrap(err, "failed to commit authentication configuration transaction")
79		}
80		return nil
81	}
